SELECT D.PROJECT_CODE, D.END_CUSTOMER, D.SCM_SITE_ID, D.ITEM_ID, D.FCST_TYPE, D.DOM_EXP, D.INCOTERMS, D.PLANT_SITE_ID, D.MEASURE, SUM(D.QTY) QTY,
 (SELECT LISTAGG(DISTINCT P.CURRENCY||':'||P.PRICE||'('||P.INCOTERMS||'/'||P.PROJECT_CODE||')', ',') FROM DM_PLN_CFM_SELLING_PRICE P
   WHERE P.DIVISION_ID=D.DIVISION_ID AND P.SCM_SITE_ID=D.SCM_SITE_ID AND P.ITEM_ID=D.ITEM_ID AND P.MEASURE='LOC' AND P.YYYYMMDD LIKE '202704%') PRICE_ANYKEY,
 (SELECT LISTAGG(DISTINCT P.CURRENCY||':'||P.PRICE, ',') FROM DM_PLN_CFM_SELLING_PRICE P
   WHERE P.DIVISION_ID=D.DIVISION_ID AND P.PROJECT_CODE=D.PROJECT_CODE AND P.SCM_SITE_ID=D.SCM_SITE_ID AND P.ITEM_ID=D.ITEM_ID AND P.FCST_TYPE=D.FCST_TYPE AND P.DOM_EXP=D.DOM_EXP AND P.INCOTERMS=D.INCOTERMS AND P.MEASURE='LOC' AND P.YYYYMMDD LIKE '202704%') PRICE_SAMEKEY
FROM DM_PLN_CFM_MKT_DEMAND_PLAN D
WHERE D.DIVISION_ID='40' AND D.YYYYMMDD LIKE '202704%' AND D.MEASURE='MKT_FCST' AND D.PROJECT_CODE IN ('NT','GREENWAY LEV','Greenway')
GROUP BY D.DIVISION_ID, D.PROJECT_CODE, D.END_CUSTOMER, D.SCM_SITE_ID, D.ITEM_ID, D.FCST_TYPE, D.DOM_EXP, D.INCOTERMS, D.PLANT_SITE_ID, D.MEASURE
ORDER BY 1,3,4
